  ('TSE-0056', 'Abundant Life Church of God', NULL, 'Cobb Resources.xlsx', '1295 Terrell Mill Rd Suite Marietta GA, 30067 Suite 104', NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '1-800-207-2356', NULL, 'lifeaccog@gmail.com', 'https://www.lifeaccog.com/', NULL, NULL, 'Shelter & Housing', NULL, 'Mission is to Provide the need of our Community through the Love of Christ and Distribution of Food and Basic Needs.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', FALSE, NULL, 'Unverified', NULL, '2nd and fourth Fridays of Every Month. 2:00pm-6:00pm Hours are subject to change due to weather or Holidays.', NULL, FALSE, NULL, now(), now()),
  ('TSE-0057', 'Home Stretch', NULL, 'Cobb Resources.xlsx', '89 Grove Way Roswell GA 30075', NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '770-642-9185 x112', NULL, NULL, 'https://homestretch.org/get-help/', NULL, NULL, 'Shelter & Housing', NULL, 'HomeStretch offers working homeless families a proven path toward financial stability, improved employment, stronger family relationships and permanent affordable housing. The HomeStretch Supportive Housing program has 23 two- and three-bedroom apartments.  Four are ADA accessible.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', FALSE, NULL, 'Unverified', NULL, 'To be eligible for the HomeStretch Supportive Housing programs, you must: Be homeless or imminently homeless. Be employed full-time - documented with pay stubs showing at least 37.5 hours worked per week. Have custody of minor child(children) in residence. Have a connection to the greater north metro Atlanta area such as employment or school.', NULL, FALSE, NULL, now(), now()),
  ('TSE-0058', 'Kids Home Initiative- Community Restoration Project', NULL, 'Cobb Resources.xlsx', NULL, NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '(Victoria) 404.604.4548', NULL, '(Victoria) vpinell@communityrestorationproject.org', 'https://www.communityrestorationproject.org/', NULL, NULL, 'Shelter & Housing', NULL, 'Kids Home Initiative is a resource for homeless and housing-instable families. CRP provides a well-rounded, individualized solution to house each family. Solutions include up to $4,000 for remedying housing barriers as well as food assistance.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', FALSE, NULL, 'Unverified', NULL, 'Must be referred by a school counselor.', NULL, FALSE, NULL, now(), now()),
