  ('TSE-0102', 'The Georgia Campaign for Adolescent Power & Potential', NULL, 'Cobb Resources.xlsx', '1849 The Exchange SE, Suite 200 Atlanta, GA 30339', NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '(404) 524-2277', NULL, 'general@gcapp.org', 'https://www.gcapp.org/who-we-are/', NULL, NULL, 'Healthcare / Medical', NULL, 'Young people in Georgia are facing enormous challenges—anxiety, depression, substance abuse, teen pregnancy, STI infections, childhood obesity, among others. Through our Formula for Change we work with every facet of the Georgia Youth eco-system to improve young people’s overall health and social well-being.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', FALSE, NULL, 'Unverified', NULL, NULL, NULL, FALSE, NULL, now(), now()),
