  ('TSE-0105', 'Second Chance Homes', NULL, 'Cobb Resources.xlsx', NULL, NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.hud.gov/program_offices/public_indian_housing/other/sch', NULL, NULL, 'Healthcare / Medical', NULL, 'Second Chance Homes are adult-supervised, supportive group homes or apartment clusters for teen mothers and their children who cannot live at home because of abuse, neglect or other extenuating circumstances.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', FALSE, NULL, 'Unverified', NULL, NULL, NULL, FALSE, NULL, now(), now()),
