  ('TSE-0156', 'Zionkeepers', NULL, 'Cobb Resources.xlsx', '324 Victory Drive Marietta, GA 30060', NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '678-388-0218', NULL, 'info@zionkeepers.org', 'https://www.zionkeepers.org/', NULL, NULL, 'Mental Health / Substance Abuse', NULL, 'homeless adult with substance abuse problem, people living with HIV/AIDS and people living with mental illness. We provide structure and stable living accommodation with nutritious meals. We provide appropriate referrals to mental health care facilities; we also provide the opportunity for education and employment assistance.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', FALSE, NULL, 'Unverified', NULL, NULL, NULL, FALSE, NULL, now(), now()),
  ('TSE-0157', 'The Extension', NULL, 'Cobb Resources.xlsx', 'P.O. Box 793, Marietta, GA 30061', NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '770-590-9075', NULL, 'info@theextension.org', 'https://theextension.org/', NULL, NULL, 'Mental Health / Substance Abuse', NULL, 'in-patient residential treatment program provides support to individuals experiencing homelessness, are over the age of 24, reside in Cobb County and can work. Program duration is nine to twelve months.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', FALSE, NULL, 'Unverified', NULL, 'There is no initial cost; however; after 30 days, our residents are required to obtain employment and pay a portion of their income toward their treatment.', NULL, FALSE, NULL, now(), now()),
  ('TSE-0158', 'The Zone', NULL, 'Cobb Resources.xlsx', '32 N Fairground St. Marietta, GA 30060', NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '770-693-5982', NULL, 'info@davisdirection.com', 'https://thezonegeorgia.com/?page_id=2', NULL, NULL, 'Mental Health / Substance Abuse', NULL, 'The Zone is a safe haven of acceptance for anyone in any stage of recovery.   It is a Recovery Community Organization (RCO) to support long-term recovery and re-entry.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', FALSE, NULL, 'Unverified', NULL, NULL, NULL, FALSE, NULL, now(), now()),
  ('TSE-0159', 'Hope for Homeowners (HUD)', NULL, 'Cobb Resources.xlsx', NULL, NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '800-225-5342', NULL, NULL, 'https://www.benefits.gov/benefit/4589', NULL, NULL, 'Shelter & Housing', NULL, 'This is a program for people at risk of losing their home due to default and foreclosure. If you are having difficulty paying your mortgage, you may be eligible to refinance into a mortgage that you can afford. Participation in the Hope for Homeowners (H4H) program is voluntary, and both lender and borrower must agree to participate.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', FALSE, NULL, 'Unverified', NULL, NULL, NULL, FALSE, NULL, now(), now()),
